// VERIFICA SESSAO SALVA
const staticData = $getWorkflowStaticData('global');
const cookies = staticData.cookies || [];
const localStorage = staticData.localStorage || {};
const ultimoLogin = staticData.ultimoLogin || null;

const agora = Date.now();
const umaHora = 60 * 60 * 1000;
const temSessao = cookies.length > 0 && ultimoLogin && (agora - new Date(ultimoLogin).getTime()) < umaHora;

return [{
  json: {
    temSessao,
    cookies,
    localStorage
  }
}];

